import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';

// Create the scene
const scene = createScene();

// OBJ file data
let vertices = [];
let faces = [];
let vertexOffset = 1; // OBJ indices start at 1

// Rotation matrix for -90 degrees around X-axis (Blender Z-up conversion)
const blenderRotation = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

// Traverse the scene and collect all geometry
scene.traverse((object) => {
  if (object.isMesh) {
    // Get the geometry
    let geometry = object.geometry;

    // Clone geometry to avoid modifying the original
    geometry = geometry.clone();

    // Get world matrix for this object
    object.updateMatrixWorld(true);
    const worldMatrix = object.matrixWorld.clone();

    // Apply world transformation to geometry
    geometry.applyMatrix4(worldMatrix);

    // Apply Blender rotation (Z-up conversion)
    geometry.applyMatrix4(blenderRotation);

    // Ensure we have position attribute
    if (!geometry.attributes.position) {
      return;
    }

    // Get position attribute
    const positions = geometry.attributes.position;
    const posArray = positions.array;

    // Get indices (if available)
    const indices = geometry.index;

    // Store vertex offset for this mesh
    const meshVertexOffset = vertexOffset;

    // Add vertices
    for (let i = 0; i < positions.count; i++) {
      const x = posArray[i * 3];
      const y = posArray[i * 3 + 1];
      const z = posArray[i * 3 + 2];
      vertices.push(`v ${x} ${y} ${z}`);
    }

    // Add faces
    if (indices) {
      // Indexed geometry
      const indexArray = indices.array;
      for (let i = 0; i < indexArray.length; i += 3) {
        const a = indexArray[i] + meshVertexOffset;
        const b = indexArray[i + 1] + meshVertexOffset;
        const c = indexArray[i + 2] + meshVertexOffset;
        faces.push(`f ${a} ${b} ${c}`);
      }
    } else {
      // Non-indexed geometry
      for (let i = 0; i < positions.count; i += 3) {
        const a = i + meshVertexOffset;
        const b = i + 1 + meshVertexOffset;
        const c = i + 2 + meshVertexOffset;
        faces.push(`f ${a} ${b} ${c}`);
      }
    }

    vertexOffset += positions.count;

  } else if (object.isInstancedMesh) {
    // Handle InstancedMesh separately
    const geometry = object.geometry.clone();
    const count = object.count;

    // Get world matrix for the InstancedMesh object itself
    object.updateMatrixWorld(true);
    const baseWorldMatrix = object.matrixWorld.clone();

    // Process each instance
    for (let i = 0; i < count; i++) {
      const instanceGeometry = geometry.clone();

      // Get instance matrix
      const instanceMatrix = new THREE.Matrix4();
      object.getMatrixAt(i, instanceMatrix);

      // Combine: base world matrix * instance matrix
      const finalMatrix = baseWorldMatrix.clone().multiply(instanceMatrix);

      // Apply transformations
      instanceGeometry.applyMatrix4(finalMatrix);
      instanceGeometry.applyMatrix4(blenderRotation);

      // Get position attribute
      const positions = instanceGeometry.attributes.position;
      const posArray = positions.array;

      // Get indices
      const indices = instanceGeometry.index;

      // Store vertex offset for this instance
      const meshVertexOffset = vertexOffset;

      // Add vertices
      for (let j = 0; j < positions.count; j++) {
        const x = posArray[j * 3];
        const y = posArray[j * 3 + 1];
        const z = posArray[j * 3 + 2];
        vertices.push(`v ${x} ${y} ${z}`);
      }

      // Add faces
      if (indices) {
        const indexArray = indices.array;
        for (let j = 0; j < indexArray.length; j += 3) {
          const a = indexArray[j] + meshVertexOffset;
          const b = indexArray[j + 1] + meshVertexOffset;
          const c = indexArray[j + 2] + meshVertexOffset;
          faces.push(`f ${a} ${b} ${c}`);
        }
      } else {
        for (let j = 0; j < positions.count; j += 3) {
          const a = j + meshVertexOffset;
          const b = j + 1 + meshVertexOffset;
          const c = j + 2 + meshVertexOffset;
          faces.push(`f ${a} ${b} ${c}`);
        }
      }

      vertexOffset += positions.count;
    }
  }
});

